INSERT INTO feature VALUES('cellular-sheaves','theory','Cellular sheaves over finite graded posets',NULL,'implemented','notable',NULL,'A cellular sheaf as a library: a stalk on each cell of a finite graded poset of up to 64 cells and a map from each cell to each cell above it, the maps checked to compose; a map is an entry map, or in a sheaf of linear maps a homomorphism of modules over the rationals, a matrix with the entry map as its fast path; the sections of a cover glued, or each pair of members that differs named with the least cell of their overlap and the first entry there; the coboundaries over the exact rationals from an orientation, refused where two in turn do not compose to zero, and the cohomology by degree; a tower of levels, each bonding map checked to commute with the coboundaries, with the rank of the map it induces on cohomology; and the reduction along a matching whose signed maps are invertible, onto cochains on the critical cells alone with the same cohomology, each pair whose map is not invertible refused by its two cells and a walk past its budget refused. The shapes crate''s face cover glues through it, the towers of the interval and the circle read their cohomology through level 5, on each whole level and on its reduct of one or two cells, and the projective line''s twist by minus two, which no entry map states, has one class in degree one.','theory-cellular-sheaves','crates/theory-cellular-sheaves/tests/sheaf.rs crates/theory-cellular-sheaves/tests/cochains.rs crates/theory-cellular-sheaves/tests/towers.rs crates/theory-cellular-sheaves/tests/reduce.rs crates/theory-cellular-sheaves/tests/linear.rs crates/theory-shapes/tests/cover.rs','crate-tests','#5506');
